#pragma once

#include <QHash>
#include <QIcon>
#include <QJsonArray>
#include <QKeySequence>
#include <QList>
#include <QString>

// Menus, accelerators, status tips and toolbars recovered from the original
// executable (generated by tools/gen_ui_spec.js into resources/ui_spec.json).
class UiSpec {
public:
    struct Toolbar {
        int resource = 0;
        QString name;
        QList<int> ids; // 0 = separator
    };

    bool load(const QString &path = QStringLiteral(":/ui_spec.json"));

    const QJsonArray &mainMenu() const { return m_mainMenu; }
    QJsonArray contextMenu(const QString &name) const { return m_contextMenus.value(name); }
    QList<QKeySequence> shortcuts(int id) const { return m_shortcuts.value(id); }
    QString statusTip(int id) const;
    QString toolTip(int id) const;
    QString undoText(int id) const { return m_undo.value(id); }
    const QList<Toolbar> &toolbars() const { return m_toolbars; }
    // Icon for a toolbar button, cut out of the original toolbar bitmap.
    QIcon icon(int id) const { return m_icons.value(id); }
    // Menu text for an id (first occurrence in the main menu), without "\t...".
    QString menuText(int id) const { return m_menuText.value(id); }

private:
    void indexMenu(const QJsonArray &items);
    void loadIcons(const Toolbar &tb);

    QJsonArray m_mainMenu;
    QHash<QString, QJsonArray> m_contextMenus;
    QHash<int, QList<QKeySequence>> m_shortcuts;
    QHash<int, QString> m_tips;
    QHash<int, QString> m_undo;
    QHash<int, QString> m_menuText;
    QHash<int, QIcon> m_icons;
    QList<Toolbar> m_toolbars;
};
